import {AccessibilityFeedbackOwner} from './foundation/global/feedback.js';
import {W03V34RunsAdapter} from './adapters/w03-runs.js';
import {
  EPISTEMIC_STATE_CONTRACT,EPISTEMIC_STATE_KINDS,EPISTEMIC_PRESENTATION_POLICY,
  EpistemicStateHost,projectEpistemicState,toAccessibilityFeedbackInput,validateEpistemicStateDescriptor
} from './foundation/contracts/epistemic-state.js';
import {
  CONFIRMATION_SAFETY_CONTRACT,CONFIRMATION_SAFETY_POLICY,ConfirmationSafetyHost,validateDestructiveRiskDescriptor
} from './foundation/global/confirmation-host.js';

const assert=(value,message='assertion failed')=>{if(!value)throw Error(message)};
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const throws=(fn,token)=>{let message='';try{fn()}catch(error){message=String(error?.message||error)}assert(message.includes(token),`expected ${token}, got ${message}`)};
const test=(tests,id,run)=>{try{run();tests.push({id,status:'PASS'})}catch(error){tests.push({id,status:'FAIL',error:String(error?.message||error)})}};

class LocalKnowledgeStateAdapter{
  constructor(){this.owner='LocalKnowledgeFixtureStateAdapter';this.revision='rev-17';this.expected='rev-18';}
  descriptor(state='EMPTY'){
    const definitions={
      EMPTY:{cause:{code:'LOCAL_QUERY_ZERO_RESULTS',query:'epistemic fixture'},meaning:{code:'NO_LOCAL_MATCH',summary:'The local fixture has no record matching the active query.'},copy:{title:'No local result',message:'The local fixture returned no matching knowledge item.'},retry:{available:false},feedbackSourceTruth:{state:'EMPTY'}},
      LOADING:{cause:{code:'LOCAL_INDEX_REBUILD_DECLARED',jobId:'fixture-index-1'},meaning:{code:'LOCAL_INDEX_PENDING',summary:'The local fixture adapter explicitly reports an unfinished index operation.'},copy:{title:'Local index is loading',message:'The local fixture index has not completed yet.'},retry:{available:false},feedbackSourceTruth:{state:'LOADING',complete:false}},
      STALE:{cause:{code:'LOCAL_REVISION_BEHIND',actual:this.revision,expected:this.expected},meaning:{code:'LOCAL_CONTENT_STALE',summary:'The local fixture revision is older than the adapter requirement.'},copy:{title:'Local content is stale',message:`Local revision ${this.revision} is behind ${this.expected}.`},retry:{available:true,actionId:'local.refresh-index',label:'Refresh local index'},feedbackSourceTruth:{state:'STALE',stale:true}},
      UNAVAILABLE:{cause:{code:'LOCAL_FIXTURE_DISABLED'},meaning:{code:'LOCAL_SOURCE_UNAVAILABLE',summary:'The local fixture source is explicitly disabled.'},copy:{title:'Local source unavailable',message:'The local fixture adapter reports the source disabled.'},retry:{available:false},feedbackSourceTruth:{state:'UNAVAILABLE',enabled:false}},
      ERROR:{cause:{code:'LOCAL_PARSE_FAILURE',record:'fixture-bad-record'},meaning:{code:'LOCAL_SOURCE_ERROR',summary:'The local fixture adapter explicitly reports a parse failure.'},copy:{title:'Local fixture error',message:'The fixture record could not be parsed.'},retry:{available:true,actionId:'local.retry-parse',label:'Retry parse'},feedbackSourceTruth:{state:'ERROR',ok:false,status:'ERROR',error:'LOCAL_PARSE_FAILURE'}}
    };
    const d=definitions[state];
    return {state,domain:{id:'local-knowledge-fixture',owner:this.owner,family:'structured'},cause:d.cause,meaning:d.meaning,copy:d.copy,retry:d.retry,canonicalTruth:{owner:this.owner,state,revision:this.revision,feedbackSourceTruth:d.feedbackSourceTruth}};
  }
}

class RuntimeEvidenceStateAdapter{
  constructor(runtime=new W03V34RunsAdapter()){this.owner='RuntimeEvidenceStateAdapter';this.runtime=runtime;}
  descriptor(state='STALE'){
    const recorded=this.runtime.recorded();
    if(state==='STALE')return {state,domain:{id:'runtime-evidence',owner:this.owner,family:'operational'},cause:{code:'RUNTIME_EPOCH_BEHIND',epoch:this.runtime.epoch,expectedEpoch:this.runtime.epoch+1},meaning:{code:'RUNTIME_EVIDENCE_STALE',summary:'The runtime evidence epoch is older than the adapter expectation.'},copy:{title:'Runtime evidence is stale',message:`Recorded run ${recorded.runId} is from epoch ${this.runtime.epoch}; a newer epoch is required.`},retry:{available:true,actionId:'runtime.refresh-evidence',label:'Refresh runtime evidence'},canonicalTruth:{owner:this.owner,state,runId:recorded.runId,epoch:this.runtime.epoch,feedbackSourceTruth:{state:'STALE',stale:true}}};
    if(state==='UNAVAILABLE'){this.runtime.disconnect();return {state,domain:{id:'runtime-evidence',owner:this.owner,family:'operational'},cause:{code:'RUNTIME_PROVIDER_DISCONNECTED',epoch:this.runtime.epoch},meaning:{code:'RUNTIME_SOURCE_UNAVAILABLE',summary:'The runtime provider explicitly reports a disconnected state.'},copy:{title:'Runtime unavailable',message:'Runtime evidence cannot be refreshed while the provider is disconnected.'},retry:{available:false},canonicalTruth:{owner:this.owner,state,connected:this.runtime.connected,epoch:this.runtime.epoch,feedbackSourceTruth:{state:'UNAVAILABLE',enabled:false}}};}
    if(state==='ERROR')return {state,domain:{id:'runtime-evidence',owner:this.owner,family:'operational'},cause:{code:'RUNTIME_RECORDED_ERROR',runId:recorded.runId},meaning:{code:'RUNTIME_EVIDENCE_ERROR',summary:'The runtime adapter explicitly reports an evidence error fixture.'},copy:{title:'Runtime evidence error',message:`Recorded run ${recorded.runId} contains an explicit error condition.`},retry:{available:false},canonicalTruth:{owner:this.owner,state,runId:recorded.runId,feedbackSourceTruth:{state:'ERROR',ok:false,status:'ERROR',error:'RUNTIME_RECORDED_ERROR'}}};
    throw Error('RUNTIME_TEST_STATE_UNSUPPORTED');
  }
}

const destructiveRisk=overrides=>({actionId:'structured.remove-subtree',sourceOwner:'StructuredActionDescriptorOwnerFixture',destructive:true,confirmationRequired:true,riskCode:'SUBTREE_DELETE',copy:{title:'Delete subtree',message:'Delete the selected subtree and its descendants?',confirmLabel:'Delete',cancelLabel:'Cancel'},canonicalTruth:{owner:'StructuredActionDescriptorOwnerFixture',selectionCount:4},scope:{count:4},...overrides});

export function runW4GEpistemicConfirmationTests(){
  const tests=[],local=new LocalKnowledgeStateAdapter(),runtime=new RuntimeEvidenceStateAdapter();
  test(tests,'w4g.contract.vocabulary',()=>{assert(EPISTEMIC_STATE_CONTRACT.id==='EpistemicStateContract');assert(same(EPISTEMIC_STATE_KINDS,['EMPTY','LOADING','STALE','UNAVAILABLE','ERROR']));assert(EPISTEMIC_STATE_CONTRACT.ownsAsyncLifecycle===false&&EPISTEMIC_STATE_CONTRACT.ownsCanonicalTruth===false)});
  test(tests,'w4g.local-and-runtime-share-host-policy',()=>{const host=new EpistemicStateHost(),a=host.project(local.descriptor('STALE')),b=host.project(runtime.descriptor('STALE'));assert(a.presentation.policyRevision===b.presentation.policyRevision);assert(a.presentation.role===b.presentation.role&&a.presentation.tone===b.presentation.tone);assert(a.cause.code!==b.cause.code&&a.copy.message!==b.copy.message&&a.domain.owner!==b.domain.owner)});
  test(tests,'w4g.loading-completion-not-invented',()=>{const p=projectEpistemicState(local.descriptor('LOADING'));assert(p.canonicalTruth.feedbackSourceTruth.complete===false);assert(!('complete' in p.presentation));assert(!('completedAt' in p)&&!('result' in p))});
  test(tests,'w4g.error-cause-not-invented',()=>{const p=projectEpistemicState(local.descriptor('ERROR'));assert(p.cause.code==='LOCAL_PARSE_FAILURE');assert(p.meaning.code==='LOCAL_SOURCE_ERROR');assert(!('inferredCause' in p)&&!('errorCause' in p.presentation))});
  test(tests,'w4g.stale-reason-not-invented',()=>{const a=projectEpistemicState(local.descriptor('STALE')),b=projectEpistemicState(runtime.descriptor('STALE'));assert(a.cause.code==='LOCAL_REVISION_BEHIND'&&b.cause.code==='RUNTIME_EPOCH_BEHIND');assert(a.cause.code!==b.cause.code)});
  test(tests,'w4g.unavailable-truth-not-invented',()=>{const d=runtime.descriptor('UNAVAILABLE'),p=projectEpistemicState(d);assert(p.canonicalTruth.connected===false&&p.canonicalTruth.feedbackSourceTruth.enabled===false);assert(!('enabled' in p.presentation))});
  test(tests,'w4g.negative.missing-cause',()=>{const d=local.descriptor('EMPTY');delete d.cause;throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_CAUSE_REQUIRED')});
  test(tests,'w4g.negative.missing-copy',()=>{const d=local.descriptor('EMPTY');delete d.copy;throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_COPY_REQUIRED')});
  test(tests,'w4g.negative.missing-retry-capability',()=>{const d=local.descriptor('EMPTY');delete d.retry;throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_RETRY_CAPABILITY_REQUIRED')});
  test(tests,'w4g.negative.missing-canonical-truth',()=>{const d=local.descriptor('EMPTY');delete d.canonicalTruth;throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_CANONICAL_TRUTH_REQUIRED')});
  test(tests,'w4g.negative.truth-state-mismatch',()=>{const d=local.descriptor('EMPTY');d.canonicalTruth.state='ERROR';throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_TRUTH_STATE_MISMATCH')});
  test(tests,'w4g.truth-conflict.error-saved-refused-before-projection',()=>{const d=local.descriptor('ERROR');d.canonicalTruth.feedbackSourceTruth={ok:true,status:'SAVED'};throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_TRUTH_CONFLICT:ERROR_PROVEN_SUCCESS');throws(()=>projectEpistemicState(d),'EPISTEMIC_TRUTH_CONFLICT:ERROR_PROVEN_SUCCESS')});
  test(tests,'w4g.truth-conflict.error-ok-true-refused',()=>{const d=local.descriptor('ERROR');d.canonicalTruth.feedbackSourceTruth={ok:true};throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_TRUTH_CONFLICT:ERROR_PROVEN_SUCCESS')});
  test(tests,'w4g.truth-conflict.unavailable-available-refused',()=>{const d=local.descriptor('UNAVAILABLE');d.canonicalTruth.feedbackSourceTruth={enabled:false,available:true};throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_TRUTH_CONFLICT:UNAVAILABLE_PROVEN_AVAILABLE')});
  test(tests,'w4g.truth-conflict.unavailable-healthy-refused',()=>{const d=local.descriptor('UNAVAILABLE');d.canonicalTruth.healthy=true;throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_TRUTH_CONFLICT:UNAVAILABLE_PROVEN_AVAILABLE')});
  test(tests,'w4g.truth-conflict.stale-fresh-refused',()=>{const d=local.descriptor('STALE');d.canonicalTruth.feedbackSourceTruth={stale:true,fresh:true};throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_TRUTH_CONFLICT:STALE_PROVEN_CURRENT')});
  test(tests,'w4g.truth-conflict.stale-current-refused',()=>{const d=local.descriptor('STALE');d.canonicalTruth.current=true;throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_TRUTH_CONFLICT:STALE_PROVEN_CURRENT')});
  test(tests,'w4g.truth-conflict.loading-complete-refused',()=>{const d=local.descriptor('LOADING');d.canonicalTruth.feedbackSourceTruth={complete:true};throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_TRUTH_CONFLICT:LOADING_PROVEN_COMPLETE')});
  test(tests,'w4g.truth-conflict.source-self-contradiction-refused',()=>{const d=local.descriptor('STALE');d.canonicalTruth.feedbackSourceTruth={ok:true,status:'ERROR',stale:true};throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_TRUTH_CONFLICT:SOURCE_TRUTH_SELF_CONTRADICTION')});
  test(tests,'w4g.truth-absence-not-inferred',()=>{const d=local.descriptor('ERROR');d.canonicalTruth.feedbackSourceTruth={state:'ERROR'};const validated=validateEpistemicStateDescriptor(d),projected=projectEpistemicState(d);assert(validated.state==='ERROR'&&projected.state==='ERROR');throws(()=>toAccessibilityFeedbackInput(d),'EPISTEMIC_FEEDBACK_BRIDGE_REFUSED:FEEDBACK_TRUTH_CONFLICT:FAILURE_NOT_PROVEN')});
  test(tests,'w4g.success-state-not-supported-no-meaning-invented',()=>{const d=local.descriptor('EMPTY');d.state='SUCCESS';d.canonicalTruth.state='SUCCESS';d.canonicalTruth.feedbackSourceTruth={ok:false,status:'ERROR'};throws(()=>validateEpistemicStateDescriptor(d),'EPISTEMIC_STATE_UNSUPPORTED:SUCCESS')});
  test(tests,'w4g.retry-intent-only',()=>{const host=new EpistemicStateHost();host.project(local.descriptor('STALE'));const r=host.retryIntent();assert(r.accepted&&r.actionId==='local.refresh-index'&&r.executesRetry===false);host.project(local.descriptor('EMPTY'));const denied=host.retryIntent();assert(!denied.accepted&&denied.code==='EPISTEMIC_RETRY_NOT_DECLARED')});
  test(tests,'w4g.accessibility-feedback-compatibility',()=>{const feedback=new AccessibilityFeedbackOwner({now:()=>1000});const unavailable=feedback.publish(toAccessibilityFeedbackInput(new RuntimeEvidenceStateAdapter().descriptor('UNAVAILABLE')));assert(unavailable.accepted&&unavailable.event.outcome==='unavailable'&&unavailable.event.source.owner==='RuntimeEvidenceStateAdapter');const error=feedback.publish(toAccessibilityFeedbackInput(local.descriptor('ERROR')));assert(error.accepted&&error.event.outcome==='error'&&error.event.source.code==='LOCAL_PARSE_FAILURE')});
  test(tests,'w4g.accessibility-feedback-all-valid-bridgeable-descriptors-pass',()=>{const descriptors=[...EPISTEMIC_STATE_KINDS.map(state=>local.descriptor(state)),runtime.descriptor('STALE'),new RuntimeEvidenceStateAdapter().descriptor('UNAVAILABLE'),new RuntimeEvidenceStateAdapter().descriptor('ERROR')];let now=2000;for(const descriptor of descriptors){const input=toAccessibilityFeedbackInput(descriptor),feedback=new AccessibilityFeedbackOwner({now:()=>++now}),result=feedback.publish(input);assert(result.accepted,`feedback rejected ${descriptor.domain.owner}:${descriptor.state}`)}});
  test(tests,'w4g.central-render-policy-both-domains',()=>{const probe={...EPISTEMIC_PRESENTATION_POLICY,revision:'w4g-probe',states:{...EPISTEMIC_PRESENTATION_POLICY.states,STALE:{...EPISTEMIC_PRESENTATION_POLICY.states.STALE,ariaLive:'assertive',tone:'probe'}}},host=new EpistemicStateHost({policy:probe});const a=host.project(local.descriptor('STALE')),b=host.project(new RuntimeEvidenceStateAdapter().descriptor('STALE'));assert(a.presentation.ariaLive==='assertive'&&b.presentation.ariaLive==='assertive'&&a.presentation.tone==='probe'&&b.presentation.tone==='probe');const reverted=new EpistemicStateHost().project(local.descriptor('STALE'));assert(reverted.presentation.ariaLive===EPISTEMIC_PRESENTATION_POLICY.states.STALE.ariaLive&&reverted.presentation.tone===EPISTEMIC_PRESENTATION_POLICY.states.STALE.tone)});
  test(tests,'w4g.confirmation.explicit-destructive',()=>{const host=new ConfirmationSafetyHost(),r=host.request({actionId:'structured.remove-subtree',risk:destructiveRisk()});assert(r.accepted&&r.code==='CONFIRMATION_PRESENTED'&&r.projection.destructive&&r.executesAction===false);const c=host.confirm(r.confirmationId);assert(c.accepted&&c.code==='CONFIRMED'&&c.authorizationOnly&&c.executesAction===false)});
  test(tests,'w4g.confirmation.no-risk-no-guess',()=>{const host=new ConfirmationSafetyHost(),r=host.request({actionId:'delete-everything'});assert(!r.accepted&&r.code==='CONFIRMATION_RISK_DESCRIPTOR_REQUIRED');assert(host.snapshot().guessesDestructiveRisk===false)});
  test(tests,'w4g.confirmation.action-name-does-not-imply-danger',()=>{const host=new ConfirmationSafetyHost(),risk=destructiveRisk({actionId:'delete-by-name-but-safe',destructive:false,confirmationRequired:false,riskCode:'EXPLICIT_SAFE'}),r=host.request({actionId:'delete-by-name-but-safe',risk});assert(r.accepted&&r.code==='CONFIRMATION_NOT_REQUIRED'&&!r.destructive)});
  test(tests,'w4g.confirmation.innocent-name-can-be-destructive',()=>{const host=new ConfirmationSafetyHost(),risk=destructiveRisk({actionId:'view.details'}),r=host.request({actionId:'view.details',risk});assert(r.accepted&&r.code==='CONFIRMATION_PRESENTED'&&r.destructive)});
  test(tests,'w4g.confirmation.contradiction-refused',()=>{throws(()=>validateDestructiveRiskDescriptor(destructiveRisk({confirmationRequired:false})),'CONFIRMATION_RISK_DESCRIPTOR_CONTRADICTION');const host=new ConfirmationSafetyHost(),r=host.request({actionId:'structured.remove-subtree',risk:destructiveRisk({confirmationRequired:false})});assert(!r.accepted&&r.code.includes('CONFIRMATION_RISK_DESCRIPTOR_CONTRADICTION'))});
  test(tests,'w4g.confirmation.central-refusal-policy-and-revert',()=>{const probe={...CONFIRMATION_SAFETY_POLICY,revision:'w4g-confirm-probe',codes:{...CONFIRMATION_SAFETY_POLICY.codes,missingRisk:'PROBE_EXPLICIT_RISK_REQUIRED'}},a=new ConfirmationSafetyHost({policy:probe}).request({actionId:'x'}),b=new ConfirmationSafetyHost().request({actionId:'x'});assert(a.code==='PROBE_EXPLICIT_RISK_REQUIRED'&&b.code===CONFIRMATION_SAFETY_POLICY.codes.missingRisk)});
  test(tests,'w4g.confirmation.contract-boundary',()=>{const host=new ConfirmationSafetyHost();assert(CONFIRMATION_SAFETY_CONTRACT.executesAction===false&&CONFIRMATION_SAFETY_CONTRACT.ownsCommandAvailability===false);for(const key of ['execute','dispatch','mutate','availability','commandRegistry','retry'])assert(!(key in host),`forbidden host ownership ${key}`)});
  return tests;
}
